MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  ColormapType
    *colormap;

  FILE
    *file;

  MagickBooleanType
    status;

  size_t
    number_colors;

  if (image == (Image *) NULL)
    return(MagickFalse);
  status=OpenBlob(image_info,image,WriteBinaryBlob,&image->exception);
  if (status == MagickFalse)
    return(status);
  number_colors=image->colors;
  if (image->colorspace != sRGBColorspace)
    (void) TransformImageColorspace(image,sRGBColorspace,&image->exception);
  if (image->colormap == (PixelInfo *) NULL)
    {
      (void) SyncImagePixels(image);
      colormap=(ColormapType *) AcquireMemory(number_colors*sizeof(*colormap));
      if (colormap == (ColormapType *) NULL)
        ThrowException(&image->exception,ResourceLimitError,"MemoryAllocationFailed","Unable to write MAP image");
      (void) memcpy(colormap,image->pixels,number_colors*sizeof(*colormap));
    }
  else
    colormap=image->colormap;
  (void) fwrite(colormap,sizeof(*colormap),number_colors,image->file);
  if (image->colormap != (ColormapType *) NULL)
    {
      register ssize_t
        x;

      for (x=0; x < (ssize_t) image->columns; x++)
        {
          register unsigned char
            index;

          index=GetPixelIndex(image,GetImagePixels(image,x,0,1,1));
          (void) fwrite(&index,sizeof(index),1,image->file);
        }
    }
  else
    {
      register ssize_t
        x;

      for (x=0; x < (ssize_t) image->columns; x++)
        {
          register unsigned char
            index;

          index=GetPixelIndex(image,GetImagePixels(image,x,0,1,1));
          (void) fwrite(&index,sizeof(index),1,image->file);
        }
    }
  (void) CloseBlob(image);
  if (image->colormap != (ColormapType *) NULL)
    colormap=(ColormapType *) RelinquishMemory(colormap);
  return(MagickTrue);
}

MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  char
    colormap[1024];

  int
    y;

  MagickBooleanType
    status;

  register const PixelPacket
    *p;

  register ssize_t
    x;

  size_t
    length;

  StringInfo
    *profile;

  FILE
    *file;

  if (image->colors > 256)
    return(MagickFalse);

  file=fopen(image_info->filename,"wb");
  if (file == (FILE *) NULL)
    return(MagickFalse);

  p=image->pixels;
  for (y=0; y < (int) image->rows; y++)
  {
    for (x=0; x < (ssize_t) image->columns; x++)
    {
      colormap[y*256+x*3+0]=(unsigned char) ScaleQuantumToChar(p->red);
      colormap[y*256+x*3+1]=(unsigned char) ScaleQuantumToChar(p->green);
      colormap[y*256+x*3+2]=(unsigned char) ScaleQuantumToChar(p->blue);
      p++;
    }
  }

  length=image->columns*image->rows*3;
  (void) fwrite(colormap,sizeof(unsigned char),length,file);

  for (y=0; y < (int) image->rows; y++)
  {
    for (x=0; x < (ssize_t) image->columns; x++)
    {
      colormap[y*256+x]=(unsigned char) p->index;
      p++;
    }
  }

  length=image->columns*image->rows;
  (void) fwrite(colormap,sizeof(unsigned char),length,file);

  (void) fclose(file);
  return(MagickTrue);
}

MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image) {
  ExceptionInfo
    *exception;

  FILE
    *file;

  MagickBooleanType
    status;

  size_t
    length;

  register ssize_t
    i;

  StringInfo
    *blob;

  exception = image->exception;
  status = MagickFalse;
  if ((file = fopen(image_info->filename,"wb")) == (FILE *) NULL) {
    (void) ThrowMagickException(exception,GetMagickModule(),FileOpenError,"UnableToCreate","%s",image_info->filename);
    return(status);
  }

  if (image->colors > 256) {
    (void) ThrowMagickException(exception,GetMagickModule(),ImageError,"NotImplemented","MAP format only supports 256 colors.");
    return(status);
  }

  /* Convert to sRGB colorspace */
  (void) SetImageColorspace(image, sRGBColorspace, exception);

  /* Allocate memory for colormap and pixel data */
  blob = AcquireStringInfo((size_t) (image->colors * 3));
  if (blob == (StringInfo *) NULL) {
    (void) fclose(file);
    (void) ThrowMagickException(exception,GetMagickModule(),ResourceLimitError,"MemoryAllocationFailed","Memory allocation failed in WriteMAPImage");
    return(status);
  }

  /* Generate colormap */
  for (i=0; i < (ssize_t) image->colors; i++) {
    PixelPacket pixel;

    pixel = GetPixelInfoPixel(image, (PixelInfo *) image->colormap[i]);
    SetStringInfoQuantum(blob, (size_t) (i * 3), pixel.red);
    SetStringInfoQuantum(blob, (size_t) (i * 3 + 1), pixel.green);
    SetStringInfoQuantum(blob, (size_t) (i * 3 + 2), pixel.blue);
  }

  length = (size_t) (image->columns * image->rows);
  (void) fwrite(StringInfoBytes(blob), sizeof(unsigned char), StringInfoLength(blob), file);
  (void) fwrite(image->indexes, sizeof(unsigned char), length, file);
  (void) fclose(file);
  RelinquishMagickResource(blob);
  status = MagickTrue;
  return(status);
}

MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  Colormap
    colormap;

  ExceptionInfo
    *exception;

  FILE
    *file;

  IndexPacket
    indexes[PixelMax + 1];

  MagickBooleanType
    status;

  register ssize_t
    i;

  register PixelIndex
    *p;

  size_t
    colormap_length,
    length;

  StringInfo
    *profile;

  unsigned char
    *pixels;

  /*
    Open output image file.
  */
  assert(image_info != (const ImageInfo *) NULL);
  assert(image_info->signature == MagickSignature);
  assert(image != (Image *) NULL);
  assert(image->signature == MagickSignature);
  if (image->debug != MagickFalse)
    (void) DebugLog("%s (MAP image format)", __func__);
  assert(image->columns > 0);
  assert(image->rows > 0);
  status = OpenBlob(image_info, image, WriteBlob, &image->exception);
  if (status == MagickFalse)
    return(status);
  file = (FILE *) image->blob;
  if (file == (FILE *) NULL)
    {
      ThrowFileException(&image->exception, FileOpenError,
        "Unable to write file", image->filename);
      return(MagickFalse);
    }
  /*
    Convert image to sRGB colorspace.
  */
  (void) TransformImageColorspace(image, sRGBColorspace);
  /*
    Allocate memory for colormap.
  */
  colormap_length = image->colors;
  if (colormap_length > (PixelMax + 1))
    colormap_length = PixelMax + 1;
  colormap = (Colormap) AcquireQuantumMemory(colormap_length,sizeof(*colormap));
  if (colormap == (Colormap) NULL)
    {
      ThrowBinaryException(ResourceLimitError,"MemoryAllocationFailed",
        image->filename);
      return(MagickFalse);
    }
  /*
    Generate colormap.
  */
  for (i=0; i < (ssize_t) colormap_length; i++)
  {
    colormap[i].red = ScaleShortToQuantum(image->colormap[i].red);
    colormap[i].green = ScaleShortToQuantum(image->colormap[i].green);
    colormap[i].blue = ScaleShortToQuantum(image->colormap[i].blue);
  }
  /*
    Write colormap to output file.
  */
  length = WriteBlobMSBShort(file,(unsigned short) colormap_length);
  if (length != sizeof(unsigned short))
    {
      status = MagickFalse;
      goto finish;
    }
  for (i=0; i < (ssize_t) colormap_length; i++)
  {
    length = WriteBlob(file,sizeof(*colormap),colormap[i]);
    if (length != sizeof(*colormap))
      {
        status = MagickFalse;
        goto finish;
      }
  }
  /*
    Write pixel indexes to output file.
  */
  pixels = (unsigned char *) AcquireQuantumMemory(image->columns,sizeof(*pixels));
  if (pixels == (unsigned char *) NULL)
    {
      ThrowBinaryException(ResourceLimitError,"MemoryAllocationFailed",
        image->filename);
      return(MagickFalse);
    }
  for (i=0; i < (ssize_t) image->rows; i++)
  {
    p = GetPixelIndexes(image);
    for (length=0; length < image->columns; length++)
      pixels[length] = (unsigned char) p[length];
    length = WriteBlob(file,image->columns,pixels);
    if (length != image->columns)
      {
        status = MagickFalse;
        goto finish;
      }
    SyncImagePixels(image);
    if (i != (ssize_t) (image->rows - 1))
      {
        exception = CatchException();
        if (exception != (ExceptionInfo *) NULL)
          {
            (void) SyncImagePixels(image);
            DestroyException(exception);
          }
      }
  }
finish:
  if (colormap != (Colormap) NULL)
    colormap = (Colormap) RelinquishMemory(colormap);
  if (pixels != (unsigned char *) NULL)
    pixels = (unsigned char *) RelinquishMemory(pixels);
  return(status);
}

MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  ColormapType
    *colormap;

  ExceptionInfo
    *exception;

  FILE
    *file;

  MagickBooleanType
    status;

  size_t
    number_colors;

  StringInfo
    *profile;

  exception = image->exception;
  status = MagickFalse;

  if ((file = fopen(image_info->filename, "wb")) == (FILE *) NULL)
  {
    (void) ThrowMagickException(exception, GetMagickModule(), FileOpenError,
      "UnableToCreate","`%s'", image_info->filename);
    return(status);
  }

  if (image->colors > 256)
    (void) TransformImageColorspace(image, sRGBColorspace);

  number_colors = (image->colors > 256) ? 256 : image->colors;

  colormap = (ColormapType *) AcquireQuantumMemory((size_t) number_colors,
    sizeof(*colormap));
  if (colormap == (ColormapType *) NULL)
  {
    (void) fclose(file);
    ThrowBinaryException(ResourceLimitError, "UnableToAllocateMemory",
      image_info->filename);
  }

  (void) memcpy(colormap, image->colormap, number_colors * sizeof(*colormap));

  if (fwrite(colormap, sizeof(*colormap), number_colors, file) != number_colors)
  {
    (void) fclose(file);
    return(status);
  }

  for ( ; ; )
  {
    register PixelIndex
      *p;

    register ssize_t
      x;

    p = (PixelIndex *) image->indexes;
    for (x = 0; x < (ssize_t) image->columns; x++)
    {
      if (fwrite(p, sizeof(*p), 1, file) != 1)
        break;
      p++;
    }
    if (x < (ssize_t) image->columns)
      break;
    if (image->next == (Image *) NULL)
      break;
    image = image->next;
  }

  status = MagickTrue;
  (void) fclose(file);
  colormap = (ColormapType *) RelinquishMagickMemory(colormap);

  return(status);
}
